/**
 * Helpers shared by the Projects viewer specs: URL builders, locators for the run view, the screenshot
 * attachment every scenario records, the per-test setup (isolated API up, mocks in worker mode) and the
 * redaction assertion used by the `paths-redacted` scenarios.
 */
import { test, expect, type APIRequestContext, type Locator, type Page, type TestInfo } from '@playwright/test'
import { waitForApi } from '../helpers.ts'
import { apiRunPath, PROJECT, WORKFLOW_ID } from './fixtures.ts'
import { verificationPhase } from './harness.ts'
import { installProjectMocks } from './mock.ts'

export const phase = verificationPhase()

export const projectsUrl = '/projects'
export const projectUrl = (projectId: string) => `/projects/${encodeURIComponent(projectId)}`
export const workflowUrl = (projectId: string, workflowId: string) => `${projectUrl(projectId)}/workflows/${encodeURIComponent(workflowId)}`
export const runUrl = (runId: string, nodeId?: string, workflowId: string = WORKFLOW_ID) => `${workflowUrl(PROJECT.project_id, workflowId)}/runs/${encodeURIComponent(runId)}${nodeId ? `/nodes/${encodeURIComponent(nodeId)}` : ''}`
export const apiRun = apiRunPath

export const workspace = (page: Page) => page.getByTestId('projects-workspace')
export const graphNode = (page: Page, nodeId: string) => page.locator(`[data-testid="workflow-graph"] [data-graph-node="${nodeId}"]`)
export const nodeListItem = (page: Page, nodeId: string) => page.locator(`[data-testid="run-node-list"] [data-node-id="${nodeId}"]`)
export const nodeDetail = (page: Page) => page.getByTestId('node-detail')
export const taskDetails = (page: Page) => page.getByTestId('task-details')

/** A launch node shows its task behind a disclosure, closed by default (PRD_VIEWER_CLARITY 4.2); this opens it. */
export async function openTask(page: Page) {
  await expect(taskDetails(page)).toBeVisible()
  if ((await taskDetails(page).getAttribute('open')) === null) await taskDetails(page).locator('summary').first().click()
  await expect(taskDetails(page)).toHaveAttribute('open', '')
}

/** No view action may launch, approve, retry, delete or edit a run: no such real controls exist (graph nodes are read-only selectors). */
export async function expectNoExecutionControls(page: Page) {
  const controls = workspace(page).locator('button, input, select, textarea, [role="menuitem"]')
  await expect(controls.filter({ hasText: /approve|retry|launch|start|resume|delete|cancel|integrate|edit|save/i })).toHaveCount(0)
  await expect(page.locator('form')).toHaveCount(0)
}

export async function attach(page: Page, testInfo: TestInfo, id: string) {
  const image = testInfo.outputPath(`${id}.png`)
  await page.screenshot({ path: image, fullPage: true })
  await testInfo.attach(`screenshot:${id}`, { path: image, contentType: 'image/png' })
}

export async function waitForProjectsApi(request: APIRequestContext) {
  if (phase !== 'candidate') return
  await expect.poll(async () => (await request.get('/api/projects')).status(), { timeout: 30_000 }).toBe(200)
}

/** Registers the suite's shared per-test setup; call once at the top level of a spec file. */
export function installHooks() {
  test.beforeEach(async ({ page, request }) => {
    await waitForApi(request)
    await waitForProjectsApi(request)
    if (phase === 'worker') await installProjectMocks(page)
  })
}

/** Reads the rendered text and asserts no absolute filesystem path (temporary root or home) leaked into it. */
export async function renderedText(locator: Locator): Promise<string> {
  const text = await locator.innerText()
  expect(text, 'rendered text must not name a temporary or home directory').not.toMatch(/\/tmp\/|\/home\//)
  return text
}

/** Fetches a URL from inside the page, so worker-mode route mocks apply exactly as they do for the app. */
export async function fetchFromPage(page: Page, url: string): Promise<{ status: number; contentType: string | null; text: string }> {
  return page.evaluate(async target => {
    const response = await fetch(target)
    return { status: response.status, contentType: response.headers.get('content-type'), text: await response.text() }
  }, url)
}

/**
 * Projects routes: `/projects[/<project>[/workflows/<workflow>[/runs/<run>[/nodes/<node>]]]]`.
 *
 * Every ID is an opaque contract identifier: it must match the shared ID pattern and is percent-encoded
 * as one path segment. Anything else is malformed rather than looked up. This domain is read-only and
 * separate from the Pi/Claude skill sources; nothing here names a filesystem path.
 */

/** Same pattern as the shared projects contract (`contracts/projects/v1.ts`). */
export const PROJECT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/

export const PROJECTS_ROUTE = 'projects'

export type ProjectsRoute =
  | { level: 'projects' }
  | { level: 'project'; projectId: string }
  | { level: 'workflow'; projectId: string; workflowId: string }
  | { level: 'run'; projectId: string; workflowId: string; runId: string; nodeId: string | null }

export function isContractId(value: string): boolean {
  return PROJECT_ID_PATTERN.test(value)
}

function encode(segments: string[]): string {
  return `/${segments.map(encodeURIComponent).join('/')}`
}

export function projectsPathname(): string {
  return `/${PROJECTS_ROUTE}`
}

export function projectPathname(projectId: string): string {
  return encode([PROJECTS_ROUTE, projectId])
}

export function workflowPathname(projectId: string, workflowId: string): string {
  return encode([PROJECTS_ROUTE, projectId, 'workflows', workflowId])
}

export function runPathname(projectId: string, workflowId: string, runId: string, nodeId: string | null = null): string {
  const segments = [PROJECTS_ROUTE, projectId, 'workflows', workflowId, 'runs', runId]
  if (nodeId !== null) segments.push('nodes', nodeId)
  return encode(segments)
}

export function routeToPathname(route: ProjectsRoute): string {
  switch (route.level) {
    case 'projects': return projectsPathname()
    case 'project': return projectPathname(route.projectId)
    case 'workflow': return workflowPathname(route.projectId, route.workflowId)
    case 'run': return runPathname(route.projectId, route.workflowId, route.runId, route.nodeId)
  }
}

/** Whether a pathname belongs to the Projects domain at all (decided before any decoding). */
export function isProjectsPathname(pathname: string): boolean {
  const first = pathname.split('/').filter(segment => segment !== '')[0]
  return first === PROJECTS_ROUTE
}

/**
 * Parses a Projects pathname. Returns null when it is not a Projects pathname or when any segment is
 * malformed (bad encoding, an invalid ID, an unexpected literal or trailing segments).
 */
export function parseProjectsPathname(pathname: string): ProjectsRoute | null {
  const raw = pathname.split('/').filter(segment => segment !== '')
  if (raw[0] !== PROJECTS_ROUTE) return null
  let segments: string[]
  try {
    segments = raw.slice(1).map(decodeURIComponent)
  } catch {
    return null
  }
  if (segments.length === 0) return { level: 'projects' }
  const [projectId, workflowsLiteral, workflowId, runsLiteral, runId, nodesLiteral, nodeId, ...rest] = segments
  if (!isContractId(projectId)) return null
  if (workflowsLiteral === undefined) return { level: 'project', projectId }
  if (workflowsLiteral !== 'workflows' || workflowId === undefined || !isContractId(workflowId)) return null
  if (runsLiteral === undefined) return { level: 'workflow', projectId, workflowId }
  if (runsLiteral !== 'runs' || runId === undefined || !isContractId(runId)) return null
  if (nodesLiteral === undefined) return { level: 'run', projectId, workflowId, runId, nodeId: null }
  if (nodesLiteral !== 'nodes' || nodeId === undefined || !isContractId(nodeId) || rest.length > 0) return null
  return { level: 'run', projectId, workflowId, runId, nodeId }
}
import { useCallback, useEffect, useRef, useState } from 'react'

export type Resource<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ready'; data: T }
  | { status: 'error'; error: unknown }

/**
 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
 * because every settled value is tagged with the request token that produced it.
 * `refreshToken` forces a reload without changing the key (the header Refresh button).
 * `pollToken` reloads in the background (live polling): the last settled value stays shown while it loads, and a
 * failed poll keeps the last loaded data instead of replacing it with an error.
 */
export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0, pollToken = 0): { state: Resource<T>; reload: () => void } {
  const [settled, setSettled] = useState<{ base: string; token: string; value: Resource<T> } | null>(null)
  const [attempt, setAttempt] = useState(0)
  const loadRef = useRef(load)
  useEffect(() => { loadRef.current = load }, [load])
  const base = key === null ? null : `${key}\u0000${attempt}\u0000${refreshToken}`
  const token = base === null ? null : `${base}\u0000${pollToken}`

  useEffect(() => {
    if (token === null || base === null) return
    const controller = new AbortController()
    loadRef.current(controller.signal).then(
      data => { if (!controller.signal.aborted) setSettled({ base, token, value: { status: 'ready', data } }) },
      error => {
        if (controller.signal.aborted) return
        setSettled(previous => previous !== null && previous.base === base && previous.value.status === 'ready'
          ? { ...previous, token }
          : { base, token, value: { status: 'error', error } })
      },
    )
    return () => controller.abort()
  }, [base, token])

  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
  const state: Resource<T> = token === null ? { status: 'idle' } : settled !== null && settled.base === base ? settled.value : { status: 'loading' }
  return { state, reload }
}
import { useEffect, useState } from 'react'

/** How often a live Projects page re-reads its run state. */
export const POLL_INTERVAL_MS = 5000

/**
 * A counter that ticks every `intervalMs` while `active` and the page is visible, and once more as the page becomes
 * visible again; pass it as a resource's `pollToken` to re-read live state in the background.
 */
export function usePoll(active: boolean, intervalMs = POLL_INTERVAL_MS): number {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    if (!active) return
    const next = () => { if (document.visibilityState === 'visible') setTick(previous => previous + 1) }
    const timer = window.setInterval(next, intervalMs)
    document.addEventListener('visibilitychange', next)
    return () => {
      window.clearInterval(timer)
      document.removeEventListener('visibilitychange', next)
    }
  }, [active, intervalMs])
  return tick
}
